class _WildcardPattern {
  final RegExp pattern;
  final String name;
  final String keyword;
  final String valueRepresentation;
  final String valueMultiplicity;
  final String retired;
  const _WildcardPattern(this.pattern, this.name, this.keyword, this.valueRepresentation, this.valueMultiplicity, this.retired);
  bool matches(String id) => pattern.hasMatch(id);
}
